const qa=`<script>artReady.then(()=>{const nav=document.createElement('nav');nav.id='treeQA';nav.style='position:fixed;top:0;left:0;right:0;z-index:240;background:#142631;color:white;padding:5px;font:11px sans-serif';nav.innerHTML='<button id="tqParty">測試開局</button><button id="tqLevel">升級一級</button><button id="tqReport">核對技能</button><button id="tqBattle">戰鬥選單</button><button id="tqExitBattle">離開測試戰鬥</button><button id="tqHide">收起測試</button><output id="tqOutput"></output>';document.body.appendChild(nav);const report=()=>{const sample={team:'hero',cls:'support',basic:'strike',alive:true,hp:10,x:0,z:0};const foe={team:'enemy',basic:'strike',alive:true,hp:10,x:1,z:0};document.querySelector('#tqOutput').textContent=JSON.stringify({edition:document.documentElement.dataset.skillEdition,phase:G.phase,party:G.party.filter(u=>u.cls).map(u=>({cls:u.cls,lv:u.lv,basic:u.basic,skills:u.skills})),tree:SkillTree.runtime.state,heroCounter:duelQA.canCounter(sample,foe),enemyCounter:duelQA.canCounter(foe,sample),bag:G.bag});};document.querySelector('#tqParty').onclick=()=>{setup.picks=[{cls:'warrior',name:'亞瑟',el:'地',col:5,lead:true},{cls:'support',name:'艾莉',el:'光',sex:'f'}];curNode=NODES.find(n=>n.id==='1-1');buildBattle();chooseZone(ZONES[0]);$('#deploy').hidden=true;$('#bottom').hidden=true;G.phase='title';show('#sTitle');report();};document.querySelector('#tqLevel').onclick=()=>{for(const u of G.party.filter(u=>u.cls))gainExp(u,expNext(u.lv)-(u.exp||0));recordParty();report();};document.querySelector('#tqReport').onclick=report;document.querySelector('#tqBattle').onclick=()=>{cur=G.party.find(u=>u.cls==='support');G.phase='battle';show('#gl');mode='act';refreshTurn();openSkills();report();};document.querySelector('#tqExitBattle').onclick=()=>{G.phase='title';$('#menu').hidden=true;$('#bottom').hidden=true;show('#sTitle');report();};document.querySelector('#tqHide').onclick=()=>nav.style.display='none';});</script>`;
